-- GEO / SEO content engine: a queue of topics, and the articles generated from
-- them (see docs/geo-seo.md).
--
-- An article is generated by the content agent (POST /api/content/generate)
-- as a *draft*. Nothing reaches the public site until an admin reads it on
-- /dashboard/admin/content and publishes it — generated text is never
-- auto-published. Published rows are what /blog, /blog/[slug], sitemap.xml and
-- /llms.txt read, all through the anon client, so the "published" RLS policy
-- below is the whole definition of "public".

create table if not exists content_topics (
  id uuid primary key default gen_random_uuid(),
  -- The working title / angle, e.g. "How to find a summer internship as a sophomore".
  topic text not null check (length(trim(topic)) > 0),
  -- The question people actually type into Google or ChatGPT. Optional, but
  -- it is the single strongest steer the generator gets.
  target_query text,
  audience text not null default 'student'
    check (audience in ('student', 'employer', 'both')),
  -- Free-form guidance for the generator: angle, things to include or avoid.
  notes text,
  status text not null default 'queued'
    check (status in ('queued', 'generating', 'generated', 'failed', 'skipped')),
  last_error text,
  created_by uuid references profiles(user_id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_content_topics_status_created
  on content_topics(status, created_at);

create table if not exists content_articles (
  id uuid primary key default gen_random_uuid(),
  -- URL segment under /blog/. Lowercase a-z, 0-9 and hyphens only; the app
  -- normalises before insert and the check keeps a hand-edited row honest.
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null check (length(trim(title)) > 0),
  -- The one-paragraph answer. Doubles as the meta description and the
  -- /llms.txt summary, so it is kept short.
  description text not null check (length(description) <= 320),
  body_markdown text not null,
  -- Answer-first summary rendered at the top of the page.
  key_takeaways text[] not null default '{}',
  -- [{ "question": "...", "answer": "..." }, ...] -> FAQPage structured data.
  faq jsonb not null default '[]'::jsonb,
  tags text[] not null default '{}',
  audience text not null default 'student'
    check (audience in ('student', 'employer', 'both')),
  target_query text,
  status text not null default 'draft'
    check (status in ('draft', 'published', 'archived')),
  topic_id uuid references content_topics(id) on delete set null,
  -- Model id for generated drafts, 'manual' for hand-written ones.
  generated_by text,
  -- Usage, prompt version, stop reason — whatever the generator wants to keep
  -- for auditing. Never rendered.
  generation_meta jsonb,
  reviewed_by uuid references profiles(user_id) on delete set null,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_content_articles_status_published
  on content_articles(status, published_at desc);

-- A published article must carry a publish date: the Article structured data
-- and the sitemap both depend on it.
alter table content_articles drop constraint if exists content_articles_published_has_date;
alter table content_articles add constraint content_articles_published_has_date
  check (status <> 'published' or published_at is not null);

drop trigger if exists set_content_topics_updated_at on content_topics;
create trigger set_content_topics_updated_at
  before update on content_topics for each row execute function update_updated_at();

drop trigger if exists set_content_articles_updated_at on content_articles;
create trigger set_content_articles_updated_at
  before update on content_articles for each row execute function update_updated_at();

alter table content_topics enable row level security;
alter table content_articles enable row level security;

-- Topics are an internal editorial queue.
drop policy if exists "Admins manage content topics" on content_topics;
create policy "Admins manage content topics"
  on content_topics for all to authenticated
  using (is_intern_first_admin(auth.uid()))
  with check (is_intern_first_admin(auth.uid()));

-- Published articles are public. This policy is what sitemap.ts, /blog and
-- /llms.txt rely on through the anon client: a draft can never be advertised
-- to a crawler because the anon client cannot read it.
drop policy if exists "Published articles are public" on content_articles;
create policy "Published articles are public"
  on content_articles for select to anon, authenticated
  using (status = 'published');

drop policy if exists "Admins manage content articles" on content_articles;
create policy "Admins manage content articles"
  on content_articles for all to authenticated
  using (is_intern_first_admin(auth.uid()))
  with check (is_intern_first_admin(auth.uid()));

comment on table content_topics is
  'Editorial queue for the GEO content agent. Queued rows are turned into content_articles drafts by POST /api/content/generate.';
comment on table content_articles is
  'Guides published at /blog/[slug]. Drafts are generated; only an admin can publish. See docs/geo-seo.md.';
